import React from "react";
import { useNavigate } from "react-router-dom";

const TextAndPatternButtons = () => {
  const navigate = useNavigate();

  const handleNavigation = (path) => {
    navigate(path);
  };

  const styles = {
    container: {
      display: "flex",
      justifyContent: "center",
      gap: "30px",
      marginTop: "100px",
    },
    button: {
      padding: "20px 40px",
      fontSize: "24px",
      fontWeight: "bold",
      color: "white",
      backgroundColor: "#1e1e2f",     // Dark background
      border: "3px solid #4caf50",    // Green border
      borderRadius: "15px",
      cursor: "pointer",
      transition: "all 0.3s ease",
      boxShadow: "0 0 10px #4caf50",   // Green glow
      textAlign: "center",
      lineHeight: "1.5",
    },
    buttonHover: {
      backgroundColor: "#4caf50",
      color: "#1e1e2f",
      boxShadow: "0 0 20px #4caf50",
    },
  };

  const [hoveredButton, setHoveredButton] = React.useState(null);

  return (
    <div style={styles.container}>
      <button
        onClick={() => handleNavigation("/UserText")}
        style={{
          ...styles.button,
          ...(hoveredButton === "text" ? styles.buttonHover : {}),
        }}
        onMouseEnter={() => setHoveredButton("text")}
        onMouseLeave={() => setHoveredButton(null)}
      >
        Text And<br />Numbers
      </button>

      <button
        onClick={() => handleNavigation("/UserPattern")}
        style={{
          ...styles.button,
          ...(hoveredButton === "pattern" ? styles.buttonHover : {}),
        }}
        onMouseEnter={() => setHoveredButton("pattern")}
        onMouseLeave={() => setHoveredButton(null)}
      >
        User Defined<br />Pattern
      </button>
    </div>
  );
};

export default TextAndPatternButtons;
